#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
__global__ void layernorm_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_buf,
    float* __restrict__ sumsq_buf,
    int N,
    int chunks)
{
    int b = blockIdx.x;
    int c = blockIdx.y;
    const float* x_ptr = x + (size_t)b * N;
    int N4 = N / 4;
    int chunk_size4 = (N4 + chunks - 1) / chunks;
    int start4 = c * chunk_size4;
    int end4 = min(start4 + chunk_size4, N4);
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr);
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float sum = 0.0f;
    float sumsq = 0.0f;
    int stride2 = nthreads * 2;
    int i = start4 + tid;
    for (; i + nthreads < end4; i += stride2) {
        float4 v0 = x_ptr4[i];
        float4 v1 = x_ptr4[i + nthreads];
        sum += v0.x + v0.y + v0.z + v0.w + v1.x + v1.y + v1.z + v1.w;
        sumsq += v0.x * v0.x + v0.y * v0.y + v0.z * v0.z + v0.w * v0.w
               + v1.x * v1.x + v1.y * v1.y + v1.z * v1.z + v1.w * v1.w;
    }
    for (; i < end4; i += nthreads) {
        float4 v = x_ptr4[i];
        sum += v.x + v.y + v.z + v.w;
        sumsq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    if (c == chunks - 1) {
        int rem_start = N4 * 4;
        for (int i = rem_start + tid; i < N; i += nthreads) {
            float v = x_ptr[i];
            sum += v;
            sumsq += v * v;
        }
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    extern __shared__ float sdata[];
    int warp_id = tid >> 5;
    int lane_id = tid & 31;
    int num_warps = (nthreads + 31) >> 5;
    if (lane_id == 0) {
        sdata[warp_id] = sum;
        sdata[num_warps + warp_id] = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        float total_sum = 0.0f;
        float total_sumsq = 0.0f;
        for (int w = 0; w < num_warps; w++) {
            total_sum += sdata[w];
            total_sumsq += sdata[num_warps + w];
        }
        atomicAdd(&sum_buf[b], total_sum);
        atomicAdd(&sumsq_buf[b], total_sumsq);
    }
