    int nthreads = blockDim.x;
    int stride2 = nthreads * 2;
    int i = start4 + tid;
    for (; i + nthreads < end4; i += stride2) {
        float4 v0 = x_ptr4[i];
        float4 w0 = w_ptr4[i];
        float4 b0 = b_ptr4[i];
        float4 v1 = x_ptr4[i + nthreads];
