        o0.y = (v0.y - mean) * inv_std * w0.y + b0.y;
        o0.z = (v0.z - mean) * inv_std * w0.z + b0.z;
        o0.w = (v0.w - mean) * inv_std * w0.w + b0.w;
        o1.x = (v1.x - mean) * inv_std * w1.x + b1.x;
        o1.y = (v1.y - mean) * inv_std * w1.y + b1.y;
        o1.z = (v1.z - mean) * inv_std * w1.z + b1.z;
        o1.w = (v1.w - mean) * inv_std * w1.w + b1.w;
        out_ptr4[i] = o0;
        out_ptr4[i + nthreads] = o1;
    }
    for (; i < end4; i += nthreads) {
        float4 v = x_ptr4[i];
        float4 w = w_ptr4[i];
        float4 bb = b_ptr4[i];
        float4 o;
        o.x = (v.x - mean) * inv_std * w.x + bb.x;
        o.y = (v.y - mean) * inv_std * w.y + bb.y;
        o.z = (v.z - mean) * inv_std * w.z + bb.z;
        o.w = (v.w - mean) * inv_std * w.w + bb.w;
        out_ptr4[i] = o;
    }
    if (c == chunks - 1) {
        int rem_start = N4 * 4;
        for (int i = rem_start + tid; i < N; i += nthreads) {
            float v = x_ptr[i];
            out_ptr[i] = (v - mean) * inv_std * weight[i] + bias[i];
        }
    }
}
